from pathlib import Path
import subprocess,json,hashlib,shutil
root=Path(__file__).resolve().parent;stage=root.parent;ev=root/'evidence';ev.mkdir(exist_ok=True)
tree=stage/'tree';bionic=(tree/'bionic').resolve();tool=(tree/'prebuilts/gcc/linux-x86/arm/arm-linux-androideabi-4.9').resolve();cc=tool/'bin/arm-linux-androideabi-gcc';ref=Path('/workspace/build01-hal-next/gralloc-link/reference');libs=ref/'system/lib';out=stage/'out-final/target/product/generic/system/lib'
flags=['-c','-std=gnu99','-O2','-fPIE','-fno-omit-frame-pointer','-fno-stack-protector','-march=armv7-a','-marm','-mfloat-abi=softfp','-mfpu=neon','-D__ANDROID__','-DANDROID','-DPLATFORM_SDK_VERSION=25','-nostdinc','-Wall','-Wextra']
for p in [bionic/'libc/include',bionic/'libc/arch-arm/include',bionic/'libc/kernel/uapi',bionic/'libc/kernel/uapi/asm-arm',bionic/'libc/kernel/android/uapi',tool/'lib/gcc/arm-linux-androideabi/4.9/include']:flags+=['-isystem',str(p)]
flags+=['-I',str(tree/'hardware/libhardware/include'),'-I',str(tree/'system/core/include')]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
records=[]
for name,src in [('crtbegin_dynamic1',bionic/'libc/arch-common/bionic/crtbegin.c'),('crtend_android',bionic/'libc/arch-common/bionic/crtend.S'),('crtbrand',bionic/'libc/arch-common/bionic/crtbrand.S'),('hal_metadata_probe',root/'hal_metadata_probe.c')]:
 output=root/(name+'.o');cmd=[str(cc),*flags,'-MD','-MF',str(ev/(name+'.d')),str(src),'-o',str(output)]
 p=subprocess.run(cmd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT);(ev/(name+'.compile.log')).write_bytes(p.stdout);assert p.returncode==0,p.stdout.decode();records.append({'source':str(src),'source_sha256':sha(src),'command':cmd,'exit_code':p.returncode,'object_sha256':sha(output)})
cmd=[str(cc),'-nostdlib','-fPIE','-pie','-march=armv7-a','-mfloat-abi=softfp','-mfpu=neon','-Wl,-e,_start','-Wl,--dynamic-linker,/system/bin/linker','-Wl,-z,defs','-Wl,--no-undefined','-Wl,--no-allow-shlib-undefined','-Wl,-z,relro','-Wl,-z,now',str(root/'crtbegin_dynamic1.o'),str(root/'crtbrand.o'),str(root/'hal_metadata_probe.o'),'-L'+str(libs),'-Wl,-rpath-link,'+str(libs),'-lc','-ldl','-lgcc',str(root/'crtend_android.o'),'-o',str(root/'hal_metadata_probe')]
p=subprocess.run(cmd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT);(ev/'probe-link.log').write_bytes(p.stdout);assert p.returncode==0,p.stdout.decode();(ev/'probe-build.json').write_text(json.dumps({'objects':records,'link':{'command':cmd,'exit_code':p.returncode},'probe_sha256':sha(root/'hal_metadata_probe')},indent=2)+'\n')
qemu=Path('/workspace/build01-hal-next/loader/bin/qemu-arm-static')
cases=[('missing-file','/nonexistent-vortex-hal.so','audio','device',2),('missing-HMI',str(libs/'libm.so'),'audio','device',3),('audio-primary',str(out/'hw/audio.primary.rk30board.so'),'audio','device',0),('audio-usb',str(out/'hw/audio.usb.default.so'),'audio','device',0),('audio-submix',str(out/'hw/audio.r_submix.default.so'),'audio','device',0),('power-module',str(out/'hw/power.default.so'),'power','module',0),('power-not-device',str(out/'hw/power.default.so'),'power','device',4),('wrong-id',str(out/'hw/audio.primary.rk30board.so'),'wrong-audio','device',4)]
checks=[]
for name,module,expected,mode,expected_exit in cases:
 cmd=[str(qemu),'-L',str(ref),'-E','LD_LIBRARY_PATH='+str(out)+':/system/lib',str(root/'hal_metadata_probe'),module,expected,mode]
 p=subprocess.run(cmd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=25);(ev/(name+'.runtime.log')).write_bytes(p.stdout);print(name,p.returncode,p.stdout.decode()[:1800]);checks.append({'case':name,'command':cmd,'exit_code':p.returncode,'expected_exit_code':expected_exit,'status':'pass' if p.returncode==expected_exit else 'fail','log':name+'.runtime.log'})
report={'scope':'Actual Android ARM32 linker with RTLD_NOW/HMI/close under QEMU usermode only. Checks tag/id/method pointers; power allows legitimate NULL open and checks hook pointers. Versions/names printed only. No HAL open or power hook invoked. Constructors/destructors may execute. No audio playback, recording, USB, HDMI, power behavior, full Android boot or hardware validation.','checks':checks,'status':'pass' if all(c['status']=='pass' for c in checks) else 'fail','inputs':[{'path':str(p),'size_bytes':p.stat().st_size,'sha256':sha(p)} for p in [qemu,root/'hal_metadata_probe',ref/'system/bin/linker']],'modules':{p.name:{'size_bytes':p.stat().st_size,'sha256':sha(p)} for p in (out/'hw').glob('*.so')}}
(ev/'loader-smoke-result.json').write_text(json.dumps(report,indent=2)+'\n');assert report['status']=='pass'
